{
  "tasks": [
    {
      "claim_id": "c1",
      "verifiable": true,
      "task": "Verify that the tool returns the sum of two integers when provided with valid integer inputs a and b, and confirm that the output is a single integer value representing a + b.",
      "reason": "This tests the core functionality and correctness of the tool's summary statement by observing actual input-output behavior under defined conditions."
    },
    {
      "claim_id": "c2",
      "verifiable": true,
      "task": "Provide inputs with non-integer values (e.g., strings or floats) and observe whether the tool rejects them with an appropriate error or fails to process, confirming it only accepts integer inputs a and b as specified in the input schema.",
      "reason": "This validates the tool's input constraints and ensures it enforces the requirement for integer parameters as defined in the input schema."
    },
    {
      "claim_id": "c3",
      "verifiable": true,
      "task": "Submit two valid integer inputs (e.g., a=3, b=5) and confirm the output is exactly 8, verifying that the tool correctly computes and returns the sum of the two integers.",
      "reason": "This directly tests the claimed computational behavior and ensures the tool performs arithmetic addition as described."
    },
    {
      "claim_id": "c4",
      "verifiable": true,
      "task": "Invoke the tool via an MCP client with a valid request containing the two integer parameters a and b, and confirm the response includes a properly typed output (integer) and adheres to the MCP protocol's expected structure (e.g., correct content type, structured response).",
      "reason": "This verifies the tool functions as a callable MCP tool with defined input and output types, ensuring compatibility with the MCP protocol specification."
    },
    {
      "claim_id": "c5",
      "verifiable": true,
      "task": "Observe the description field of the 'a' property in the input schema when the tool is queried or serialized, and confirm it reads exactly 'The first integer to be added'.",
      "reason": "This tests the accuracy and completeness of the schema metadata as specified in the claim."
    },
    {
      "claim_id": "c6",
      "verifiable": true,
      "task": "Observe the description field of the 'b' property in the input schema when the tool is queried or serialized, and confirm it reads exactly 'The second integer to be added'.",
      "reason": "This tests the accuracy and completeness of the schema metadata as specified in the claim."
    }
  ]
}
